#include <Imlib2.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <assert.h>
#include <stdio.h>
int main(void){Imlib_Image im=imlib_create_image(4,4);assert(im);imlib_context_set_image(im);imlib_context_set_color(255,0,0,255);imlib_image_fill_rectangle(0,0,4,4);imlib_image_set_format("png");Imlib_Load_Error e;imlib_save_image_with_error_return("/tmp/imlib-test.png",&e);assert(e==IMLIB_LOAD_ERROR_NONE);imlib_free_image();im=imlib_load_image_immediately_without_cache("/tmp/imlib-test.png");assert(im);imlib_context_set_image(im);assert(imlib_image_get_width()==4);DATA32*p=imlib_image_get_data_for_reading_only();for(int i=0;i<16;i++)assert((p[i]&0xffffff)==0xff0000);Imlib_Image scaled=imlib_create_cropped_scaled_image(0,0,4,4,16,16);assert(scaled);imlib_free_image();imlib_context_set_image(scaled);Display*d=XOpenDisplay(NULL);assert(d);Window w=XCreateSimpleWindow(d,DefaultRootWindow(d),0,0,32,32,0,0,0);XMapWindow(d,w);XSync(d,False);imlib_context_set_display(d);imlib_context_set_visual(DefaultVisual(d,DefaultScreen(d)));imlib_context_set_colormap(DefaultColormap(d,DefaultScreen(d)));imlib_context_set_drawable(w);imlib_render_image_on_drawable(0,0);XSync(d,False);XImage*x=XGetImage(d,w,0,0,16,16,AllPlanes,ZPixmap);assert(x);for(int y=0;y<16;y++)for(int x1=0;x1<16;x1++)assert((XGetPixel(x,x1,y)&0xffffff)==0xff0000);XDestroyImage(x);imlib_image_set_format("jpeg");imlib_save_image_with_error_return("/tmp/imlib-test.jpg",&e);assert(e==IMLIB_LOAD_ERROR_NONE);imlib_free_image();im=imlib_load_image_immediately_without_cache("/tmp/imlib-test.jpg");assert(im);imlib_context_set_image(im);assert(imlib_image_get_width()==16);p=imlib_image_get_data_for_reading_only();for(int i=0;i<256;i++){assert(((p[i]>>16)&255)>245);assert(((p[i]>>8)&255)<10);assert((p[i]&255)<10);}imlib_free_image();assert(!imlib_load_image("/tmp/no-such-image.png"));XDestroyWindow(d,w);XCloseDisplay(d);puts("IMLIB2-PASS");return 0;}
